create or replace function public.guard_student_attempt_start() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is not null and public.current_app_role()='STUDENT' then if new.student_id<>auth.uid() then raise exception 'Attempt owner must be signed-in student'; end if; new.started_at=now(); new.status='IN_PROGRESS'; new.submitted_at=null; new.graded_at=null; new.total_score=null; end if; return new; end $$;
create trigger student_attempt_start_guard before insert on public.assessment_attempts for each row execute function public.guard_student_attempt_start();
create or replace function public.guard_student_submission_state() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare v_end timestamptz; begin if auth.uid() is null or public.current_app_role()<>'STUDENT' then return new; end if; if tg_table_name='assessment_attempts' and tg_op='UPDATE' then if old.student_id<>auth.uid() or old.status<>'IN_PROGRESS' then raise exception 'Submitted attempt is locked'; end if; if new.started_at is distinct from old.started_at or new.total_score is distinct from old.total_score or new.graded_at is distinct from old.graded_at then raise exception 'Attempt timestamps and grade are protected'; end if; if new.status='SUBMITTED' then select least(old.started_at+make_interval(mins=>a.duration_minutes),a.close_at) into v_end from public.assessments a where a.id=old.assessment_id; if now()>v_end then raise exception 'Assessment time window has ended'; end if; new.submitted_at=now(); elsif new.submitted_at is distinct from old.submitted_at then raise exception 'Submission time is server controlled'; end if; end if; if tg_table_name='assignment_submissions' and tg_op='UPDATE' then if old.student_id<>auth.uid() or new.status is distinct from old.status or new.submitted_at is distinct from old.submitted_at or new.graded_at is distinct from old.graded_at or new.graded_by is distinct from old.graded_by then raise exception 'Submission state and timestamps cannot be changed by students'; end if; if new.text_content is distinct from old.text_content or new.storage_path is distinct from old.storage_path then new.is_edited=true; end if; end if; return new; end $$;
create or replace function public.guard_assessment_answer_window() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare v_end timestamptz; begin if auth.uid() is not null and public.current_app_role()='STUDENT' then select least(a.started_at+make_interval(mins=>e.duration_minutes),e.close_at) into v_end from public.assessment_attempts a join public.assessments e on e.id=a.assessment_id where a.id=new.attempt_id and a.student_id=auth.uid() and a.status='IN_PROGRESS'; if v_end is null or now()>v_end then raise exception 'Assessment time window has ended'; end if; end if; return new; end $$;
create trigger student_answer_window before insert or update on public.submission_answers for each row execute function public.guard_assessment_answer_window();
